export type MaturityAnswers = Record<string, MaturityResult>
export type RiskAnswers   = Record<string, RiskLevel>

export interface CRAMeta {
  organization: string
  unit: string
  assessor: string
  date: string
  sector: string
}

export function calcDomainCRA(domainId: string, answers: MaturityAnswers) {
  const domain = DOMAINS_CRA.find(d => d.id === domainId)
  if (!domain) return { pct: 0, pass: 0, partial: 0, fail: 0, alt: 0, na: 0, total: 0 }
  let pass = 0, partial = 0, fail = 0, alt = 0, na = 0
  for (const item of domain.items) {
    const s = answers[item.id] ?? ''
    if (s === 'pass') pass++
    else if (s === 'partial') partial++
    else if (s === 'fail') fail++
    else if (s === 'alt') { alt++; pass++ } // alternative control counts as pass
    else if (s === 'na') na++
  }
  const total = domain.items.length
  const scored = total - na
  const pct = scored > 0 ? Math.round(((pass + partial * 0.5) / scored) * 100) : 0
  return { pct, pass, partial, fail, alt, na, total }
}

export function calcOverallCRA(answers: MaturityAnswers) {
  let totalPass = 0, totalPartial = 0, totalScored = 0
  for (const d of DOMAINS_CRA) {
    const r = calcDomainCRA(d.id, answers)
    totalPass    += r.pass
    totalPartial += r.partial
    totalScored  += r.total - r.na
  }
  return totalScored > 0 ? Math.round(((totalPass + totalPartial * 0.5) / totalScored) * 100) : 0
}

export function calcIRLevel(categoryId: string, answers: RiskAnswers): 'low' | 'medium' | 'high' | 'none' {
  const cat = IR_CATEGORIES.find(c => c.id === categoryId)
  if (!cat) return 'none'
  let hasHigh = false, hasMed = false
  for (const f of cat.factors) {
    const r = answers[f.id] ?? ''
    if (r === 'high') hasHigh = true
    else if (r === 'medium') hasMed = true
  }
  if (hasHigh) return 'high'
  if (hasMed) return 'medium'
  const answered = cat.factors.some(f => answers[f.id] && answers[f.id] !== '')
  return answered ? 'low' : 'none'
}

export function calcOverallIRLevel(answers: RiskAnswers): 'low' | 'medium' | 'high' | 'none' {
  const levels = IR_CATEGORIES.map(c => calcIRLevel(c.id, answers))
  if (levels.includes('high')) return 'high'
  if (levels.includes('medium')) return 'medium'
  if (levels.includes('low')) return 'low'
  return 'none'
}

export function getMaturityStatus(pct: number) {
  if (pct === 0) return { label: 'ยังไม่ประเมิน', color: 'text-muted-foreground', bg: 'bg-secondary', dot: 'bg-muted-foreground' }
  if (pct >= 80) return { label: 'พร้อม', color: 'text-emerald-500', bg: 'bg-emerald-500/10', dot: 'bg-emerald-500' }
  if (pct >= 50) return { label: 'กำลังพัฒนา', color: 'text-amber-500', bg: 'bg-amber-500/10', dot: 'bg-amber-500' }
  return { label: 'ต้องปรับปรุง', color: 'text-red-500', bg: 'bg-red-500/10', dot: 'bg-red-500' }
}

export function getRiskBadge(level: 'low' | 'medium' | 'high' | 'none') {
  if (level === 'high')   return { label: 'สูง',      color: 'text-red-500',              bg: 'bg-red-500/10',     dot: 'bg-red-500'     }
  if (level === 'medium') return { label: 'ปานกลาง', color: 'text-amber-500',            bg: 'bg-amber-500/10',   dot: 'bg-amber-500'   }
  if (level === 'low')    return { label: 'ต่ำ',      color: 'text-emerald-500',          bg: 'bg-emerald-500/10', dot: 'bg-emerald-500' }
  return                          { label: 'ยังไม่ตอบ', color: 'text-muted-foreground',   bg: 'bg-secondary',      dot: 'bg-muted-foreground' }
}

export const TOTAL_MATURITY_ITEMS = DOMAINS_CRA.reduce((s, d) => s + d.items.length, 0)
export const TOTAL_IR_FACTORS     = IR_CATEGORIES.reduce((s, c) => s + c.factors.length, 0)
